package com.servicehub.config; import com.servicehub.domain.*; import com.servicehub.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@Configuration public class SeedData { @Bean CommandLineRunner demoUsers(UserRepository users){return args->{if(users.count()>0)return; BCryptPasswordEncoder p=new BCryptPasswordEncoder(); make(users,p,"admin@servicehub.local","Jordan Davis",Role.ADMIN);make(users,p,"amelia@servicehub.local","Amelia Harper",Role.EMPLOYEE);make(users,p,"customer@servicehub.local","Nimbus Systems",Role.CUSTOMER);};} private void make(UserRepository r,BCryptPasswordEncoder p,String email,String name,Role role){AppUser u=new AppUser();u.setEmail(email);u.setDisplayName(name);u.setRole(role);u.setPasswordHash(p.encode("Password123!"));r.save(u);} }
